// One job per component; the page composes them.
function header() {
  return "<header>Shop</header>";
}
function main() {
  return "<main>Items</main>";
}
function footer() {
  return "<footer>2026</footer>";
}
function renderPage() {
  return header() + main() + footer();
}
console.log(renderPage());

