// Repetition becomes a component: map data to components.
function itemLi(item) {
  return "<li>" + item + "</li>";
}
function renderList(items) {
  return "<ul>" + items.map(itemLi).join("") + "</ul>";
}
console.log(renderList(["a", "b"]));

